inline void randomFailureWithStatus(Gen& g, Failure& f, uint32_t status) {
    f.status = status;
    if (status == 0) {
        f.domain.reset();
        f.code = 0;
        f.message.clear();
        return;
    }
    if (status == 1) {
        f.domain = g.ownString(g.stringLength());
        f.code = g.i64();
    } else {
        f.domain.reset();
        f.code = 0;
    }
    f.message = g.ownString(g.stringLength());
}
